import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';
import { orbit, depthRotate, dissolveMorph, displacementTransition, parallaxScroll, magneticCursor, particleEmerge, flyThrough, kineticText } from '@/primitives';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry for the textured plane
  const geometry = new PlaneGeometry(7, 6); // size matches backdrop spec but can be adjusted; using generic size

  // Basic material (no lighting)
  const material = new MeshBasicNodeMaterial({ color: 0xffffff });

  // Mesh
  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {
      // texture load failure is silent; keep material without map
    });
  }

  // Apply cinematic primitives if any (none in this spec, but keep generic handling)
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params ?? {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Text content handling (none for this node, but placeholder for future)
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize,
      color: item.role && config.visual?.colors?.[item.role] ? config.visual.colors[item.role] : '#e8ecf2',
      align: 'left',
    });
    root.add(txt);
  }

  // User data for event handlers and cleanup
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose primitives
    for (const inst of primitiveInstances) {
      if (inst && typeof inst.cleanup === 'function') {
        inst.cleanup();
      }
    }
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Kill any GSAP timelines (none created here but defensively)
    gsap.globalTimeline.clear(true);
  };

  return root;
}
